pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address logger, bool status, address checker) public {
        vm.assume(logger != address(0));
        vm.assume(checker != address(0));
        vm.assume(logger != checker);
        // Owner sets approved logger
        address owner = address(this);
        vm.startPrank(owner);
        bool success;
        try c.setApprovedLogger(logger, status) { success = true; } catch { success = false; }
        vm.stopPrank();
        // General rule: after a successful setApprovedLogger call by owner, the value for logger
        // matches the given status when read from a different caller.
        if (success) {
            vm.prank(checker);
            assertEq(c.approvedLoggers(logger), status);
        } else {
            // If call failed (shouldn't for owner), just assert true
            assertTrue(true);
        }
    }
}

