    function setUp() public { c = new C(); }
    function testFuzz_property(address logger, bool status, address caller) public {
        vm.assume(logger != address(0));
        vm.assume(caller != address(0));
        // Set the caller as the contract owner to be able to call setApprovedLogger
        vm.store(address(c), bytes32(0), bytes32(uint256(uint160(caller))));
        vm.prank(caller);
        c.setApprovedLogger(logger, status);
        // Now have the logger try to log an event; the return value should reflect the intended status
        vm.prank(logger);
        bool logResult = c.logFunded();
        // Reference: logResult == status; Bug: logResult != status due to flipped storage
        assertTrue(logResult == status);
    }
}

