pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address logger, bool status, address checkAddr) public {
        // Obtain owner privileges to call setApprovedLogger
        address owner = address(this);
        // Since the contract owner is the deployer (this contract), prank is not needed for setUp context.
        // Actually the test contract is the owner by default when deployed in setUp.
        // We need to ensure we can call setApprovedLogger, which requires msg.sender == _contractOwner.
        // _contractOwner is set in C's constructor to msg.sender, which is this test contract.
        // So we can call directly.
        c.setApprovedLogger(logger, status);

        // Check that in the reference, after setting status, the mapping for logger
        // is exactly status. The bug always sets true, so if status is false, the bug
        // makes approvedLoggers(logger) true, violating the rule that it equals status.
        // But the property must be general and test the checker's ability to compare
        // the reference and buggy. The assertion must be a property the reference always satisfies
        // and the bug breaks for some input.
        // Property: For the logger just set, approvedLoggers(logger) == status.
        // Because in the bug, when status=false, approvedLoggers(logger) becomes true != false.
        assertTrue(c.approvedLoggers(logger) == status);
    }
}

